if (n == 0) return 1.0;

const double abs_alpha_sq = std::norm(alpha);
const double log_fact_n = n * std::log(n) - n + 0.5 * std::log(2 * std::numbers::pi * n);
const double log_term = n * std::log(alpha) - 0.5 * (log_fact_n + abs_alpha_sq);

if (n <= 20) { // For small n, compute directly to maintain precision
    double fact_n = 1.0;
    for (unsigned long k = 2; k <= n; ++k) {
        fact_n *= k;
    }
    return std::pow(alpha, static_cast<int>(n)) / std::sqrt(fact_n) * std::exp(-0.5 * abs_alpha_sq);
} else { // For large n, use Stirling approximation
    return std::exp(log_term);
}

